using namespace std;
int main() {
    int n;
    cin >> n;
    vector<string> words(n);
    for (auto &w : words) cin >> w;
    string prefix = words[0];
    for (int k = 1; k < n; k++) {
        size_t i = 0;
        while (i < prefix.size() && i < words[k].size() && prefix[i] == words[k][i]) i++;
        prefix.resize(i);
    }
    cout << (prefix.empty() ? "-" : prefix) << "\n";
    return 0;
}

